INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES
(698, 'koKR', 'Braki w zapasach', 'Zbieram zapasy dla naszej placówki przy plaży na wschodzie – Tok\'Kar robi, co może, ale między wartami a gotowaniem dla żołnierzy niewiele mu zostaje czasu w ciągu dnia.$B$BLubią upiec sobie trochę mięsa piłozęba, kiedy tylko mogą, ale nie miałem czasu wysłać im kolejnej dostawy. Pomożesz im?$B$BMłode piłozęby nie są tak smaczne jak starsze, więc trzymaj się od nich z daleka; daj im rok czy dwa, niech urosną.', 'Przynieś 8 nieprzyrządzonych udźców piłozęba Tok\'Karowi na Moczarach Smutków.', '', 'Wróć do Tok\'Kara w Posterunku Mglistej Trzciny na Moczarach Smutków.', '', '', '', '', 0),
(699, 'koKR', 'Braki w zapasach', 'Przez murloki na wybrzeżu stacjonujemy tutaj, żeby chronić Stonard przed nadciągającymi zagrożeniami – albo ostrzec go, jeśli wróg będzie zbyt liczny. Nie zostaje nam wiele czasu na odpoczynek i przydałaby się pomoc, jeśli możesz.$B$BSzczypce piłozębych kłapaczy po odpowiedniej obróbce nadają się na świetną broń. Przynieś mi trochę tych szczypiec, a w podzięce za świeże mięso i dobre towarzystwo dostaniesz jedną z naszych broni.', 'Przynieś 6 szczypiec piłozębych kłapaczy Tok\'Karowi na Moczarach Smutków.', '', 'Wróć do Tok\'Kara w Posterunku Mglistej Trzciny na Moczarach Smutków.', '', '', '', '', 0),
(1389, 'koKR', 'Kryształy draenetystu', 'Zagubieni, którzy żyją w Ugorowym Sanktuarium, wyglądają jak my, ale to potwory... oszalałe od trudów naszej podróży do Azeroth. Niegdyś nasi bracia, teraz żyją w Ugorowym Sanktuarium na wschodzie i chwytają lub zabijają każdego, kto zabłądzi w pobliże.$B$BUkradli nam też coś świętego – kryształy draenetystu.$B$BNie mamy dość sił, by wkroczyć do Ugorowego Sanktuarium i odebrać skradziony draenetyst spomiędzy ich chat i ognisk, ale bez tych kryształów... my również możemy się zagubić.', 'Przynieś 6 kryształów draenetystu Magtoorowi w Przystani na Moczarach Smutków.', '', 'Wróć do Magtoora na Moczarach Smutków.', '', '', '', '', 0),
(1392, 'koKR', 'Noboru Maczuga', 'Noboru od miesięcy nęka draenei z Przystani, a jego maczuga jest symbolem okrucieństwa, jakiego zaznali z rąk Zagubionych.', 'Zanieś Maczugę Noboru przywódcy Przystani na Moczarach Smutków.', '', '', '', '', '', '', 0),
(1393, 'koKR', 'Ucieczka Galena', 'Pomocy! Te stwory chcą mnie zjeść!$B$BWydostań mnie stąd, a dam ci wspaniały skarb! Jest w moim obozie na bagnach na północ od Stonardu, ale zamknąłem go w szkatule, którą można otworzyć tylko sztuczką znaną wyłącznie mnie.$B$BJeśli pomożesz mi uciec, zdradzę ci ją.', 'Wyprowadź Galena w bezpieczne miejsce, a potem odnajdź jego obóz na Moczarach Smutków i otwórz jego szkatułę.', 'Wyprowadź Galena z Ugorowego Sanktuarium.', 'Znajdź Szkatułę Galena przy Sadzawce Łez na Moczarach Smutków.', '', '', '', '', 0),
(1396, 'koKR', 'Napierająca zwierzyna', 'Moja karawana zmierzała na wschodnie wybrzeże, ale nie dotarliśmy do celu. Zagubieni napadli na nas, zabili strażników i porozrzucali zapasy.$B$BTylko ja przeżyłem ich atak. Przysiągłem chronić to, co zostało z zapasów, ale w pobliżu czają się dzikie stwory. Proszę, pomóż mi obronić obóz przed bestiami!', 'Zabij 8 młodych piłozębych krokoliszków, 10 prządek smutku i 10 bagiennych jaguarów, a potem wróć do wartownika Biggsa na Moczarach Smutków.', '', 'Wróć do wartownika Biggsa na Moczarach Smutków.', '', '', '', '', 0),
(1398, 'koKR', 'Dryfujące drewno', 'Wiele ci zawdzięczam, $N. W twojej piersi bije honorowe serce. A teraz mam kolejne zadanie, w którym pokornie proszę cię o pomoc.$B$BJeśli mam kiedykolwiek dotrzeć do Strażnicy Otchłani, muszę naprawić ten wóz. A do tego... potrzebuję drewna. Mocnego, suchego drewna – nie gąbczastego, poskręcanego drewna bagiennych drzew.$B$B$N, idź na wschód, na wybrzeże, i poszukaj wyrzuconego przez morze drewna, wysuszonego przez słońce. Przynieś mi je.', 'Przynieś 8 kawałków wysuszonego dryfującego drewna wartownikowi Biggsowi na Moczarach Smutków.', '', 'Wróć do wartownika Biggsa na Moczarach Smutków.', '', '', '', '', 0),
(1421, 'koKR', 'Zaginiona karawana', 'Podczas ataku Zagubionych zostałem ogłuszony, ale zanim pociemniało mi w oczach, dostrzegłem, jak jeden z naszych wozów jest ciągnięty do Ugorowego Sanktuarium, wioski Zagubionych na północy.$B$BW tym wozie była skrzynia z karawany z cennymi składnikami, niezbędnymi w badaniach czarodziejów ze Strażnicy Otchłani. Znajdź skrzynię i zdobądź te składniki, $N. Zdobądź je i przynieś mi.', 'Znajdź Skrzynię z karawany w Ugorowym Sanktuarium, zdobądź składniki czarodziejów i przynieś je wartownikowi Biggsowi.', '', 'Wróć do wartownika Biggsa na Moczarach Smutków.', '', '', '', '', 0),
(1422, 'koKR', 'Zagrożenie od morza', 'Kiedy ja zabiorę się za twoją broń, może porozmawiasz z Katarem? Wspominał, że potrzebuje pomocy przy patrolach na plaży, a wolałbym, żebyś $gzachował:zachowała; trzeźwy umysł i broń w gotowości, zamiast upijać się z resztą tych wszy, z którymi dzielę obóz.', 'Porozmawiaj z Katarem na Moczarach Smutków.', '', '', '', '', '', '', 0),
(1423, 'koKR', 'Zagubione zapasy', 'Ta baryłka jest mała, ale solidna. Jej szwy uszczelniono żółtym, ostro pachnącym woskiem. Na dnie baryłki wybito słowa:$B$BKWATERMISTRZ LUNGERTZ$B$BSTRAŻNICA OTCHŁANI', 'Zanieś zagubione zapasy kwatermistrzowi Lungertzowi.', '', '', '', '', '', '', 0),
(1424, 'koKR', 'Sadzawka Łez', 'Wódz wysłał nas, byśmy zbadali dziwne wydarzenia w Świątyni Atal\'Hakkar.$b$bTrolle Atal\'ai to plemię mrocznych czarowników, znanych z uprawiania zakazanej magii. Wyobraź sobie nasze zdumienie, gdy po przybyciu odkryliśmy, że świątynia została zatopiona.$b$bTeraz strzegą jej zielone smoki, które twierdzą, że są obrońcami Azeroth.$b$bMusimy się dowiedzieć, co się stało. Zbadaj okolice Sadzawki Łez i zbierz artefakty Atal\'ai. Na ich podstawie zacznę składać tę układankę w całość.', 'Fel\'zerul ze Stonardu chce, żebyś $gzebrał:zebrała; 5 artefaktów Atal\'ai.', '', 'Wróć do Fel\'zerula na Moczarach Smutków.', '', '', '', '', 0),
(1425, 'koKR', 'Dostarcz przesyłkę', 'Kiedy ja będę naprawiał ten wóz, $N, mam dla ciebie ostatnie zadanie.$B$BSpakowałem najważniejsze zapasy ocalałe po atakach ogrów. Zanieś je do Strażnicy Otchłani. Twierdza leży wśród północnych wzgórz Jałowych Ziem i strzeże Mrocznego Portalu.$B$BAby dotrzeć do Strażnicy Otchłani, idź drogą na wschód. Gdy się rozwidli, skręć na południe, na Jałowe Ziemie, a na następnym rozstaju skręć w lewo. Trzymaj się drogi, $N, i uważaj.', 'Zanieś dostawę kwatermistrzowi Lungertzowi w Strażnicy Otchłani.', '', '', '', '', '', '', 0),
(1426, 'koKR', 'Zagrożenie od morza', 'Nie kocham morza ani żadnego stworzenia, które widziałem wychodzące z jego głębin. To potężna, lecz ślepa pani; bezduszna i brutalna. Z wielką przyjemnością zabijałbym ryboludzi setkami, gdyby tylko było to w mojej mocy. Czerpię jednak pewną przyjemność z patrzenia, jak giną z rąk tych, którzy wypełniają wolę Hordy.$B$BI tu wkraczasz ty, $N. Ilu zdołasz zabić? Zmierzysz się z najpotężniejszymi z nich?', 'Zabij 10 bagiennych murloków, 10 bagiennych atramentoplujów i 10 bagiennych pożeraczy ciał, a potem wróć do Katara na Moczarach Smutków.', '', 'Wróć do Katara na Moczarach Smutków.', '', '', '', '', 0),
(1427, 'koKR', 'Zagrożenie od morza', 'Zanim odpoczniesz, porozmawiaj jeszcze raz z Tok\'Karem. Chyba skończył kilka broni, kiedy cię nie było. Za twoją pomoc tutaj zaoferuje ci jedną z nich. Dobrze zrobisz, jeśli sprawdzisz jej siłę na ryboludziach, gdy będziesz $ggotów:gotowa;... choćby po to, by jeszcze bardziej mnie zadowolić.', 'Porozmawiaj z Tok\'Karem na Moczarach Smutków.', '', '', '', '', '', '', 0),
(1428, 'koKR', 'Nieustające zagrożenie', 'Cieszy mnie, że twoja nienawiść do ryboludzi rośnie razem z moją.$B$BZnajdź więcej ich pobratymców na plaży, a gdy będziesz $gsyty:syta; walki, wróć do mnie. Wtedy porozmawiamy o nagrodzie za twoją gorliwość.', 'Zabij 10 bagiennych atramentoplujów, 10 bagiennych pożeraczy ciał i 10 bagiennych wyroczni, a potem wróć do Katara na Moczarach Smutków.', '', 'Wróć do Katara na Moczarach Smutków.', '', '', '', '', 0),
(1429, 'koKR', 'Wygnaniec Atal\'ai', 'Gdy $gstawiałeś:stawiałaś; czoła niebezpieczeństwom Sadzawki Łez, jeden z moich zwiadowców wrócił ze zwojem spisanym krwią na wysuszonej skórze. Wygląda na wyrok skazujący kapłana z plemienia Atal\'ai.$b$bKapłana tego skazano na los, który wśród Atal\'ai uchodzi za gorszy od śmierci.$b$bWygnano go daleko na północ, do Zaziemia, by żył wśród trolli Suchokorych.$b$bZwiążę te artefakty w pakunek. Odszukaj wygnańca i dowiedz się, do czego naprawdę służą. Gdy zakończysz podróż, wróć do mnie.', 'Zanieś pakunek artefaktów Atal\'ai Wygnańcowi Atal\'ai w Zaziemiu.', '', '', '', '', '', '', 0),
(1430, 'koKR', 'Świeże mięso', 'Moi klienci bardzo cenią sobie soczysty smak mięsa pełzaczy, zwłaszcza monstrualnych pełzaczy.$B$BJeśli wybierasz się na wybrzeże, sowicie ci zapłacę za przyniesienie mi ich odnóży, które wyślę do Orgrimmaru.$B$BWybrzeże leży stąd na wschód, a te stwory bez trudu znajdziesz, jak przemykają po plażach i pod wodą.', 'Przynieś 10 odnóży monstrualnych pełzaczy Darowi na Moczarach Smutków.', '', 'Wróć do Dara w Stonardzie na Moczarach Smutków.', '', '', '', '', 0),
(1444, 'koKR', 'Powrót do Fel\'Zerula', 'Jammal\'an Prorok skazał mnie na wygnanie ze Świątyni Atal\'Hakkar. Kiedyś uważałem arcykapłana za godnego przywódcę.$b$bJego niezachwiana wiara w proroctwo doprowadzi Atal\'ai do zguby. O ile już nie doprowadziła.$b$bGdy wyraziłem swoje obawy, okrzyknięto mnie niewiernym i wypędzono ze świątyni.$b$bArtefakty, które mi $gprzyniosłeś:przyniosłaś;, są nieszkodliwe. Ale jeśli Jammal\'an znalazł właściwe zaczarowanie fetyszy do rytuału przywołania, światu grozi wielkie niebezpieczeństwo...', 'Wróć do Fel\'Zerula w Stonardzie.', '', '', '', '', '', '', 0),
(1445, 'koKR', 'Świątynia Atal\'Hakkar', 'A więc mówił o proroctwie Jammal\'ana?$b$bDuchowy przywódca Atal\'ai wierzy, że gdy Hakkar powróci do Azeroth z Otchłani, bóg obdarzy plemię Atal\'ai nieśmiertelnością.$b$bJak dla mnie to głupie oszustwo, które tylko przybliży dzień zagłady.$b$bAle mówisz, że wygnaniec wspominał o zaczarowanych fetyszach? To mnie bardzo niepokoi. Jeśli to one są kluczem do rytuału Atal\'ai, który wywołał ten bałagan, musimy poznać ich wewnętrzną moc.$b$bWyrusz do Świątyni i zdobądź fetysze!', 'Zbierz 20 fetyszy Hakkara i zanieś je Fel\'Zerulowi w Stonardzie.', '', 'Wróć do Fel\'zerula na Moczarach Smutków.', '', '', '', '', 0),
(2621, 'koKR', 'Zhańbiony', 'Żal. Tylko to mi teraz zostało. Jedna zła decyzja, która pociągnęła za sobą wiele strasznych skutków. Gdybym tylko zaczekał na te rozkazy. Może opisywały okropności, które czekały na nas w tych przeklętych krainach! Może miały nas skierować do innego zadania? Ostatecznie to moja wina. Wszystko to moja wina.$B$BI tak stoję tu, czekając na rozkazy. Muszę wiedzieć. Muszę dostać te rozkazy.$B$BDowódca wypraw Ruag przebywa w Stonardzie. Znajdź go i dowiedz się, co się stało z rozkazami.$B', 'Porozmawiaj z dowódcą wypraw Ruagiem w Stonardzie na Moczarach Smutków.', '', '', '', '', '', '', 0),
(2622, 'koKR', 'Zaginione rozkazy', 'Rozkazy? A na co ci niby te rozkazy?$B$BCo sugerujesz, $N? Oczywiście, że przekazałem te rozkazy! Żołnierzy, którym je powierzyłem, napadły i brutalnie pobiły murloki. Przeżył tylko jeden, jeśli można to nazwać przeżyciem. Ledwie mówi, nie może chodzić i trzeba go karmić przez rurkę. Jeśli chcesz wiedzieć, co się stało z rozkazami, porozmawiaj z Bengorem. Na pewno kręci się gdzieś w pobliżu... i, $N, uważaj, gdzie wtykasz nos – mogą ci go odgryźć.', 'Porozmawiaj z Bengorem w Stonardzie na Moczarach Smutków.', '', '', '', '', '', '', 0),
(2623, 'koKR', 'Mówca Bagien', 'Rozkazy dał dowódca wypraw. Wzięliśmy... wzięliśmy rozkazy. W drodze na Jałowe Ziemie zasadzka.$B$BMurloki... Dużo murloków... Jeden zwał się Mówca Bagien. Wyrwał mi rozkazy z rąk, kiedy włócznia wbiła mi się w czaszkę. Wschód... jaskinia...$B$B<Bengor traci przytomność.>$B', 'Odzyskaj rozkazy wodza i zanieś je Poległemu bohaterowi Hordy.', '', 'Wróć do Poległego bohatera Hordy na Rozstajach Strzaskanej Włóczni na Moczarach Smutków.', '', '', '', '', 0),
(2681, 'koKR', 'Kamienie, które nas wiążą', 'W pojedynkę nie pokonasz sił Razelikha i jego podwładnych.$B$BZbierz odpowiednią drużynę poszukiwaczy przygód i uwolnij moich ludzi od wiecznych tortur! Musisz roztrzaskać osiemnaście kamieni.$B$BWalcz zaciekle i giń z honorem, $N.', 'Uwolnij dziewięciu sług Razelikha, trzech sług Sevine, trzech sług Allistarja i trzech sług Grola. Gdy wykonasz zadanie, wróć do Poległego bohatera. Musisz pozostawać blisko kamieni, inaczej proces się nie powiedzie.', '', 'Wróć do Poległego bohatera Hordy na Rozstajach Strzaskanej Włóczni na Moczarach Smutków.', 'Uwolnieni słudzy Razelikha', 'Uwolnieni słudzy Grola', 'Uwolnieni słudzy Allistarja', 'Uwolnieni słudzy Sevine', 0),
(2701, 'koKR', 'Bohaterowie dawnych dni', 'Proszę, weź stąd relikt z dawnych czasów. Nam już się nie przyda.$B$BNiech dobrze ci służy w walce z Legionem.$B', 'Otwórz skrzynię i odbierz nagrodę.', '', '', '', '', '', '', 0),
(2702, 'koKR', 'Bohaterowie dawnych dni', '$GUhonorowałeś:Uhonorowałaś; mnie swoją szlachetnością i bohaterstwem, $N.$B$B$GUhonorowałeś:Uhonorowałaś; także ich...', 'Porozmawiaj z kapralem Thundem Rozszczepionym Kopytem.', '', '', '', '', '', '', 0),
(2721, 'koKR', 'Kirith', 'Gdy zamyka się jeden rozdział twojej przygody, otwiera się kolejny, $N.$B$BLos jednego z moich ludzi wciąż jest nieznany – zaginął gdzieś na Jałowych Ziemiach. Chodzi oczywiście o porucznika Kiritha.$B$BJak już wspominałem, obaj byliśmy więzieni i torturowani przez Allistarja, ale biedny Kirith... jego siła woli się załamała. Z mojej klatki słyszałem eksperymenty; udręczone krzyki niosły się korytarzami jaskini. Wtedy ostatni raz widziałem Kiritha i ostatni raz o nim słyszałem.', 'Dowiedz się, co się stało z porucznikiem Kirithem.', '', '', '', '', '', '', 0),
(2743, 'koKR', 'Pod osłoną ciemności', 'Nie traćmy czasu na słowa; mój czas tutaj jest ograniczony.$B$BMusisz zniszczyć triadę mocy, która chroni władcę demonów, Razelikha. Nie będzie to tak proste, jak uwolnienie potępionej duszy.$B$B<Kirith uśmiecha się szeroko.>$B$BWidzisz, każdy z podwładnych Razelikha nosi na szyi jedną trzecią amuletu, który stworzył Razelikh. Tego samego amuletu, którego będziesz potrzebować, by przywołać arcydemona.$B$BWróć do Trebora i powiedz mu, czego trzeba, by przywołać Razelikha. On udzieli ci dalszych wskazówek.', 'Wróć do Poległego bohatera Hordy i przekaż mu, czego się $gdowiedziałeś:dowiedziałaś;.', '', '', '', '', '', '', 0),
(2744, 'koKR', 'Łowca demonów', 'Triady strzeże Razelikh.$B$BW zamian za służbę Razelikh obdarzył każdego z nich niemal nieograniczoną mocą na Jałowych Ziemiach. Każdy fragment amuletu jest dostrojony do siły życiowej swojego właściciela i zapewnia mu nieśmiertelność. Dopóki pozostają na Jałowych Ziemiach, nie można ich zabić, a ich życie trwa aż do końca dni.$B$BJest ktoś, kto może ci dalej pomóc, $N. Udaj się do Aszary i odnajdź łowcę demonów, Loramusa Thalipedesa. Przeszukaj wyspy.', 'Porozmawiaj z Loramusem Thalipedesem w Aszarze.', 'Rozmowa z Loramusem', 'Wróć do Loramusa Thalipedesa w Zatoce Burz w Aszarze.', '', '', '', '', 0),
(2783, 'koKR', 'Drobne sprzeczki', 'Walczymy z niewłaściwym wrogiem, $N.$B$BPrawdziwa potęga tych ziem wciąż rośnie w siłę i liczebność, podczas gdy my kłócimy się z orkami o spaloną ziemię.$B$BCzy mamy dalej toczyć na tych ziemiach wojnę z Hordą tylko po to, by pewnego dnia rozgromiły nas armie Płonącego Legionu? To daremne.$B$BOdłóż na bok dawne waśnie, $N, i porozmawiaj z Poległym bohaterem Hordy. On zna prawdę o Jałowych Ziemiach.', 'Porozmawiaj z Poległym bohaterem Hordy na granicy Jałowych Ziem i bagien.', '', '', '', '', '', '', 0),
(2784, 'koKR', 'Niełaska', 'Wysłuchaj mojej opowieści.', 'Wysłuchaj opowieści Poległego bohatera Hordy.', 'Opowieść o smutku', 'Wróć do Poległego bohatera Hordy na Rozstajach Strzaskanej Włóczni na Moczarach Smutków.', '', '', '', '', 0),
(2801, 'koKR', 'Opowieść o smutku', 'Zanim pójdziemy dalej, musisz wysłuchać mojej opowieści.', 'Wysłuchaj opowieści Poległego bohatera Hordy.', 'Opowieść o smutku', 'Wróć do Poległego bohatera Hordy na Rozstajach Strzaskanej Włóczni na Moczarach Smutków.', '', '', '', '', 0),
(3374, 'koKR', 'Esencja Eranikusa', 'Uruchamiasz Kamień przysięgi, a Itharius przemawia przez niego wprost do twojego umysłu.$B$B„Przyjmując powinność zawartą w tym Kamieniu przysięgi, zgadzasz się wspierać moją sprawę i sprawę Stada Ysery w odkupieniu wypaczonej duszy Eranikusa. Pierwszą ofiarą – jedną z wielu, które ty i ja bez wątpienia poniesiemy – będzie oddanie mi klejnotu, który więzi to, co pozostało z wolnej części jaźni Eranikusa.”$B$B„Zrób to, $N, a razem odkupimy duszę godną odkupienia.”', 'Zanieś kamień przysięgi Stada Ysery i skutą esencję Eranikusa Ithariusowi na Moczarach Smutków. Tam zdecydujesz, czy wesprzesz Stado Ysery.', '', '', '', '', '', '', 0),
(3512, 'koKR', 'Słowami Eranikusa', '$N, naszym pierwszym krokiem będzie znalezienie sposobu, by porozmawiać z Eranikusem przez klejnot. Tkwi teraz w niepewnym stanie między snem a śmiercią, uwikłany w sieć koszmarów. Choć esencja, którą mi $gdałeś:dałaś;, jest mocno skażona, być może zdołamy do niego dotrzeć.$B$BUdaj się daleko, do lodowych krain wschodniego Zimozdroju, i odszukaj jednego z naszych śmiertelnych sojuszników – to Umbranse Mówca Duchów. To ludzki medium, który przemawia w imieniu zmarłych. Choć Eranikus nie jest naprawdę martwy, Umbranse wciąż może nam pomóc.', 'Udaj się do wschodniej części Zimozdroju i porozmawiaj z Umbranse, Mówcą Duchów.', '', '', '', '', '', '', 0),
(3627, 'koKR', 'Scalenie roztrzaskanego amuletu', 'Aby dotrzeć do Plugawiciela, musisz najpierw zniszczyć triadę mocy i odzyskać fragmenty amuletu. Gdy odzyskasz wszystkie trzy, wróć do mnie, a udzielę ci dalszych wskazówek.$B$BIdź, $N! Na Jałowe Ziemie! Sevine, Allistarj i Grol muszą paść!$B', 'Zabij Grola Niszczyciela, Lady Sevine i arcymaga Allistarja. Zabierz z ich zwłok amulet Grola, amulet Sevine i amulet Allistarja.$B$BPamiętaj, by UŻYĆ zaczarowanej azsharytowej broni zguby spaczenia, aby osłabić triadę. Inaczej nie da się ich zabić – ale używaj jej rozważnie...$B', '', 'Wróć do Poległego bohatera Hordy na Rozstajach Strzaskanej Włóczni na Moczarach Smutków.', '', '', '', '', 0),
(3628, 'koKR', 'Jesteś Rakh\'likh, demonie', 'Leże Razelikha znajduje się na szczycie najwyższej góry Jałowych Ziem. Jedyną drogą do leża są runy teleportacji w pobliżu góry. Dopóki masz przy sobie amulet, możesz swobodnie przenieść się do leża. Gdy tam dotrzesz, musisz przywołać bestię. Amulet jest twoim kluczem, $N. Użyj go przy Ołtarzu Plugawiciela.$B$BJeśli pokonasz Plugawiciela, przynieś jego róg. Stanie się symbolem nadziei dla wszystkich, którzy go ujrzą – dowodem, że w tym rozdartym wojną świecie wciąż istnieją bohaterowie.$B', 'Zniszcz Razelikha Plugawiciela i zanieś odcięty róg Plugawiciela Poległemu bohaterowi Hordy. Musisz też oddać osłonę Plugawiciela, aby Poległy bohater mógł ją zniszczyć, żeby nigdy nie wpadła w niepowołane ręce.$B', '', 'Wróć do Poległego bohatera Hordy na Rozstajach Strzaskanej Włóczni na Moczarach Smutków.', '', '', '', '', 0),
(8423, 'koKR', 'Braterstwo wojowników', '<Bohater przygląda ci się uważnie.>$b$bNie ma wątpliwości, że jesteś $gwojownikiem:wojowniczką;. Poprosiłbym cię o honorowe zadanie, ale muszę sprawdzić twoją siłę.$b$bPowiadają, że Rexxar sprawdzał ostrość swoich ostrzy, zabijając piekielnego dzika jednym szybkim ciosem. Ja zmierzę twoją siłę tym, jak będziesz je zabijać.', 'Zabij 7 piekielnych dzików na Jałowych Ziemiach i wróć do Poległego bohatera Hordy.', '', 'Wróć do Poległego bohatera Hordy na Rozstajach Strzaskanej Włóczni na Moczarach Smutków.', '', '', '', '', 0),
(8424, 'koKR', 'Wojna z Cienioprzysięgłymi', 'Ciągła obecność Cienioprzysięgłych na Jałowych Ziemiach sprawia mi wielki ból. Ich mroczne rytuały i zaklęcia zadają mi katusze, jakich nie czułem za życia.$b$bPrzez ciebie mogę im przekazać własne przesłanie bólu. Idź i nieś mój gniew.', 'Wyrżnij Cienioprzysięgłych na Jałowych Ziemiach i wróć do Poległego bohatera Hordy.', '', 'Wróć do Poległego bohatera Hordy na Rozstajach Strzaskanej Włóczni na Moczarach Smutków.', '', '', '', '', 0),
(8425, 'koKR', 'Pióra wudu', 'Twój honor przyniósł mi nieco spokoju. Wypada, bym ofiarował ci coś w zamian.$b$bZa życia moja broń i zbroja były wspaniałe, lecz teraz na nic mi się nie zdadzą. Lepiej przysłużą się tobie.$b$bUdaj się do zatopionej świątyni i zniszcz trollich strażników: Gashera, Mijana, Zola, Hukku, Zul\'lora i Lora. Mają przy sobie magiczne pióra, które mogą odtworzyć moje ciało na tyle długo, bym zdołał dać ci nagrodę.', 'Przynieś pióra wudu od trolli z Zatopionej Świątyni Poległemu bohaterowi Hordy.', '', 'Wróć do Poległego bohatera Hordy na Rozstajach Strzaskanej Włóczni na Moczarach Smutków.', '', '', '', '', 0),
(9440, 'koKR', 'Małe kąski', 'Udoskonalam broń przeciwko draenei, a ty mi w tym pomożesz!$B$BZagubieni to zacofani kuzyni draenei, a ja przeprowadzam na nich eksperymenty. Musisz tylko nakarmić kąskami skażonymi spaczeniem zwierzęta, które trzymają w niewoli. A kiedy zarżną i zjedzą te zwierzęta, zostaną przeklęci! To pokaże temu nadętemu anachorecie Avuunowi z Przystani!$B$BIdź już, pospiesz się! Zagubionych i ich zwierzęta w klatkach znajdziesz na północnym wschodzie, w Ugorowym Sanktuarium.', 'Nakarm kąskami skażonymi spaczeniem zwierzęta schwytane przez Zagubionych. Potem zanieś resztki Cersei Śpiewaczce Zmierzchu w Stonardzie na Moczarach Smutków.', '', 'Wróć do Cersei Śpiewaczki Zmierzchu na Moczarach Smutków.', 'Nakarmiony schwytany krokoliszek', 'Nakarmiony schwytany jaguar', 'Nakarmiona schwytana tarantula', '', 0),
(9448, 'koKR', 'Litość dla przeklętych', 'Ta wiedźma, krwawa elfka Cersei Śpiewaczka Zmierzchu, rzuca klątwy na Zagubionych, jestem tego pewien! Nie wiem, dlaczego ani jak, ale skutki są tragiczne. Kilkoro Zagubionych zostało jeszcze bardziej wypaczonych – przeklętych jeszcze większą dawką energii spaczenia!$B$B$N, czy znajdziesz w sobie litość dla tych biednych stworzeń? Nie powinny dożywać swoich dni w tak strasznym stanie.$B$BTych przeklętych Zagubionych znajdziesz w Ugorowym Sanktuarium, na wschód w dół ścieżki.', 'Zabij 3 przeklętych Zagubionych, a potem wróć do anachorety Avuuna w Przystani na Moczarach Smutków.', '', 'Wróć do anachorety Avuuna na Moczarach Smutków.', '', '', '', '', 0),
(9609, 'koKR', 'Pomóż wartownikowi Biggsowi', 'Magtoor powiedział mi, że w pobliżu utknął pewien wartownik. Podobno karawanę, którą eskortował z Mrocznych Włości, zaatakowali Zagubieni. Wygląda na to, że tylko on przeżył.$B$BJest gdzieś na południu. Proszę, $N, pomóż mu.', 'Znajdź wartownika Biggsa na Moczarach Smutków.', '', '', '', '', '', '', 0),
(9610, 'koKR', 'Sadzawka Łez', 'Interesuję się przeszłością Azeroth i zastanawiam się, czy zechcesz mi pomóc.$B$BNa bagnach, niedaleko stąd, jest miejsce o znaczeniu historycznym, do którego chciałbym cię wysłać. Na południowym wschodzie leży Sadzawka Łez. Powiadają, że na jej brzegach i w jej głębinach spoczywają zakopane artefakty cywilizacji trolli Atal\'ai.$B$BAle uważaj, strzeże jej Somnus, pradawny zielony smok, i jego drakanie, a w samej sadzawce żyją mięsożerne ryby!', 'Zdobądź 5 artefaktów Atal\'ai i zanieś je Holaaru w Przystani na Moczarach Smutków.', '', 'Wróć do Holaaru na Moczarach Smutków.', '', '', '', '', 0);
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES
(698, 'koKR', 'Ach! Wspaniale. Świeże mięso na dzisiejsze ognisko. Dzięki, $N.$b$bDzięki tobie nadchodzące noce będą znośniejsze. Ogień płonie jasno, a nasze brzuchy będą pełne.$b$bMiła niespodzianka, że to ty $gprzyniosłeś:przyniosłaś; nam dostawę; Dar nie jest najprzystojniejszym orkiem, na jakiego ktokolwiek patrzył, ale przynajmniej jego charakter cuchnie o wiele mniej niż on sam.', 0),
(699, 'koKR', 'Dobrze widzieć cię $gcałego:całą; i $gzdrowego:zdrową;, $N.$b$bTe szczypce świetnie się nadadzą. Im więcej broni mamy w gotowości na wypadek ataku, tym lepiej dla nas.$b$bZabiorę się za twoją broń najszybciej, jak się da. To zajmie tylko chwilę. Nabrałem sporej wprawy i szybkości w ich wyrabianiu.', 0),
(1389, 'koKR', 'Dziękuję, $N. Jesteśmy twoimi dłużnikami.', 0),
(1392, 'koKR', '$GZdobyłeś:Zdobyłaś; broń budzącego grozę Noboru? Czyżby więc nie żył?$B$BTo radosny dzień dla Przystani. Noboru i jego banda siali wśród nas postrach – krążyli po bagnach i zabijali każdego draenei, który stanął im na drodze. Zagrażał samemu naszemu przetrwaniu, a nie mieliśmy dość sił, by się z nim zmierzyć.$B$BMamy szczęście, że jesteś naszym $gprzyjacielem:przyjaciółką;, $N.', 0),
(1393, 'koKR', 'Dziurkę od klucza w tej szkatule zalano czarną żywicą. Nie da się jej otworzyć.$b$bAle Galen powiedział ci o ukrytym zatrzasku na spodzie skrzynki... $b$b...Po krótkich poszukiwaniach znajdujesz zatrzask. Przestawiasz go i szkatuła się otwiera...', 0),
(1396, 'koKR', 'Odgłosy zwierząt są teraz słabe, bardziej odległe. Dziękuję, $N. Miejmy nadzieję, że nie wrócą!', 0),
(1398, 'koKR', 'To drewno jest lekkie, ale wytrzymałe. Dziękuję, $N. Świetnie się nada.', 0),
(1421, 'koKR', 'Ach, $gznalazłeś:znalazłaś; je! Dzięki nim czarodzieje ze Strażnicy Otchłani będą mogli kontynuować pracę. Nie wiem, czym dokładnie się zajmują, ale ma to związek z Mrocznym Portalem na Jałowych Ziemiach i jest niezbędne dla bezpieczeństwa Przymierza.', 0),
(1422, 'koKR', 'Zamilknij na chwilę, $N. Nawet mimo głuchego ryku morza wciąż słychać to obrzydliwe bulgotanie ryboludzi.', 0),
(1423, 'koKR', 'Ach, dziękuję, $N! Tyle zapasów ginie po drodze z Mrocznych Włości tutaj. Dobrze widzieć, że część udaje się odzyskać.', 0),
(1424, 'koKR', 'Twoja pilność w zbieraniu artefaktów Atal\'ai zasługuje na pochwałę, $N.', 0),
(1425, 'koKR', 'Co? Paczka z karawany Biggsa? Myśleliśmy, że przepadła, a on razem z nią.$B$BDziękuję, $N. Przy odrobinie szczęścia w tych zapasach znajdzie się tak bardzo potrzebny składnik – kryształy azoranu. Nasze zapasy się kończą...', 0),
(1426, 'koKR', 'Morze wydaje się bezkresne i nieubłagane, ale $gsplamiłeś:splamiłaś; je krwią jego własnego pomiotu. Ryboludzie poznali ból. Przez swoją głupotę będą musieli odbudowywać szeregi po spustoszeniu, które $gspowodowałeś:spowodowałaś;, i to dobrze.$B$BNiech ich bulgoczące wrzaski zagłuszają ryk morza do późnej nocy. Będę się uśmiechał za każdym razem, gdy usłyszę, że któryś z nich zamilkł.$B$BWróć do mnie, jeśli zechcesz zabić więcej ryboludzi. Chętnie znów cię nagrodzę.', 0),
(1427, 'koKR', 'Ach, $N, $gwróciłeś:wróciłaś;. Dobrze. Skończyłem wykuwać kolejną partię broni do walki z murlokami. Za to, że $gprzyniosłeś:przyniosłaś; nam świeże mięso piłozęba, i za to, że $gwywołałeś:wywołałaś; lekki uśmiech na twarzy Katara, daję ci jedną z nich.', 0),
(1428, 'koKR', 'Dobra robota, $N. Pragnę więcej ich krwi. Niech wyginą wszyscy ryboludzie.', 0),
(1429, 'koKR', 'Przynosisz mi artefakty przywołania Atal\'ai?$b$bWidzę, że Jammal\'an Prorok prowadzi uczniów Komnaty Krwi ku wybranemu przez nich losowi. Ciekawe, czy Hakkar powrócił do Świątyni? Czy ich los się dopełnił?', 0),
(1430, 'koKR', 'Ach, będą idealne. Nie mogę się doczekać, aż ich spróbuję, kiedy zostaną porządnie upieczone nad otwartym ogniem. Weź trochę na drogę. Naprawdę pyszne.', 0),
(1444, 'koKR', 'Minęło sporo czasu, odkąd rozmawialiśmy, $N. Mam nadzieję, że twoja podróż się powiodła.$b$bCzego $gdowiedziałeś:dowiedziałaś; się od wygnanego Atal\'ai w Zaziemiu?', 0),
(1445, 'koKR', '$GDzielny:Dzielna; $N, $gdowiodłeś:dowiodłaś;, że jesteś $gwielkim czempionem:wielką czempionką; Hordy.$b$bTeraz trzeba natychmiast zająć się tymi fetyszami Hakkara!', 0),
(2621, 'koKR', 'Uścisk Thralla... Ta historia wciąż jest świeża w mojej pamięci.$b$b<Dowódca Ruag kręci głową>$b$bStraszna rzecz spotkała ten oddział. Horda straciła część swoich najlepszych żołnierzy, gdy zniszczono ten batalion.', 0),
(2622, 'koKR', 'Mó... mówca... Mówca Ba... Bagien...$b$b', 0),
(2623, 'koKR', 'Jest gorzej, niż sobie wyobrażałem. Dziewiętnastu moich ludzi mogło uniknąć męki, która ich spotkała. Gdybym tylko nie działał tak nierozważnie.$b$bMusisz im pomóc, $N! Ja nic nie mogę zrobić.', 0),
(2681, 'koKR', 'Udało ci się, $N! Biedne, udręczone dusze mogą wreszcie spocząć.$b$bNasza praca jeszcze się nie skończyła, $N. Mamy wiele do omówienia i jeszcze więcej do zrobienia.', 0),
(2701, 'koKR', 'Blask i połysk na chwilę cię oślepiają.', 0),
(2702, 'koKR', 'Zaiste, $guhonorowałeś:uhonorowałaś; nas wszystkich. Same podziękowania to za mało.', 0),
(2721, 'koKR', 'Trebor? Przysłał cię Trebor?', 0),
(2743, 'koKR', 'Władca demonów wykazuje się przebiegłością niemal tak wyrachowaną jak jego okrucieństwo, $N.', 0),
(2744, 'koKR', 'Pomogę ci. Choć nie sądzę, byś w pełni $grozumiał:rozumiała;, z czym się mierzysz.', 0),
(2783, 'koKR', 'Przymierze chce pomóc?$B$BMyślałem, że nigdy więcej nie doczekam takiego dnia. Dnia, w którym Przymierze walczy ramię w ramię z Hordą przeciw wspólnemu wrogowi.$B$BNiech tak będzie... zjednoczymy się.', 0),
(2784, 'koKR', 'Jako duch jestem bezsilny, $N. Pomóż mi. Pozwól mi odzyskać honor.', 0),
(2801, 'koKR', 'Czas działać, $N.', 0),
(3374, 'koKR', '$GDokonałeś:Dokonałaś; wyboru, i tak to się zaczyna. Twoje dotychczasowe wybory uważam za słuszne; to twoje czyny od tej chwili zadecydują, czy tak pozostanie.', 0),
(3512, 'koKR', 'Itharius mądrze zrobił, przysyłając cię do mnie. Choć Eranikus nie jest martwy w takim sensie, w jakim ty rozumiesz śmierć, wkrótce udzieli nam rady własnymi słowami. Na razie jednak nie mogę ci bezpośrednio pomóc... przynajmniej jeszcze nie.$b$bUżyczę ci swojej umiejętności rozmowy ze zmarłymi, ale najpierw potrzebuję pomocy kogoś, kogo – w przeciwieństwie do mnie – nie ograniczają słabości starości. Wbrew mojej woli odebrano mi moje najpotężniejsze narzędzie wróżebne, a jeśli go nie odzyskam, nie zdołamy pomóc Eranikusowi.', 0),
(3627, 'koKR', 'Amulet Razelikha Plugawiciela znów jest cały, ale Razelikh wyczuwa zakłócenie w swoim łańcuchu dowodzenia. Wie, że po niego idziesz...', 0),
(3628, 'koKR', 'Ten dzień będzie pamiętany przez całą wieczność. Demoniczny władca Jałowych Ziem wreszcie upadł!', 0),
(8423, 'koKR', 'Nie potrzebuję dowodu, by wiedzieć, czego $gdokonałeś:dokonałaś;, $N. Widzę determinację wyrytą na twojej twarzy.', 0),
(8424, 'koKR', 'Już $gzłagodziłeś:złagodziłaś; mój ból i $goddałeś:oddałaś; mi cześć. Dziękuję, $N.', 0),
(8425, 'koKR', 'Nareszcie znów czuję zimny dotyk stali, choćby tylko przez chwilę.', 0),
(9440, 'koKR', 'Och, doskonale! Nie mogę się doczekać, aż zmierzę efekty tej najnowszej partii!$B$BCóż, $gspisałeś:spisałaś; się godnie, kochanie. Szkoda, że nie mogę ci dać więcej za tę rozrywkę, ale $gsam:sama; wiesz, jak jest. Na bagnach nie da się zarobić wielkich pieniędzy.$B$BJestem pewna, że dla samej zabawy było warto!', 0),
(9448, 'koKR', 'A więc stało się. Dziękuję, że $gokazałeś:okazałaś; współczucie. Gdy wypaczyło ich to, czym karmiła ich Cersei, nic więcej nie dało się zrobić.$B$BTeraz zaznali spokoju, a mam nadzieję, że moje badania nad pozostałymi przyniosą owoce i uda się ich uleczyć.', 0),
(9609, 'koKR', 'Co? Przysłał cię tu draenei z Przystani? Dziwne.$B$BCóż, nie zwykłem odmawiać pomocy. Dzięki, że $gprzyszedłeś:przyszłaś;, $N!', 0),
(9610, 'koKR', 'Dziękuję, $N. Badanie tych artefaktów zajmie mnie na jakiś czas. Jak my, Złamani i draenei, mamy się tu odnaleźć, jeśli nie zrozumiemy historii waszego świata?', 0);
INSERT INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES
(698, 'koKR', 'Lok\'tar, $N. Wędrówka przez bagna to niemałe ryzyko. $GOdważny:Odważna; jesteś, skoro sprawdzasz tu swoje siły.', 0),
(699, 'koKR', 'Dobry miód, ciepłe ognisko, armia orków i arsenał broni... niczego więcej nam tu, na wybrzeżu, nie trzeba. Nie żałuję, że pilnuję tu Stonardu, ale fajnie byłoby kiedyś dostać ziemiankę, albo chociaż wieżę.', 0),
(1389, 'koKR', 'Masz kryształy?', 0),
(1392, 'koKR', 'Pozdrawiam. Witaj w Przystani.', 0),
(1396, 'koKR', 'Bagienne stwory podchodzą coraz bliżej, $N. Proszę, musisz obronić obóz!', 0),
(1398, 'koKR', '$GZnalazłeś:Znalazłaś; jakieś dryfujące drewno, $N?', 0),
(1421, 'koKR', 'Masz składniki czarodziejów, $N?', 0),
(1424, 'koKR', 'Nikt nie wie, jakie mroczne praktyki odprawiano w Świątyni Atal\'Hakkar. Wiemy jednak, że użyto tam wielkich i potężnych sił magii.$b$bMusimy się dowiedzieć o tej magii jak najwięcej. Może zaklęcia Atal\'ai okażą się przydatne dla Hordy.$b$bGdy zbierzesz dość artefaktów Atal\'ai z okolic Sadzawki Łez, zacznę rozumieć, co trolle chciały osiągnąć i co poszło tak straszliwie nie tak.', 0),
(1425, 'koKR', 'Masz do mnie jakąś sprawę?', 0),
(1426, 'koKR', 'Jestem cierpliwy. Cierpliwy i wieczny jak stary kamień z Draenoru. Ryboludzie nie przedostaną się przez nasze granice – nie, póki stoję na nogach. Gdybyśmy mieli do dyspozycji armię, oczyściłbym z nich ten świat i wszystkie inne. Czuję, jak kipi we mnie nienawiść, gdy tylko o nich mówię.', 0),
(1428, 'koKR', 'Nie zaznam zadowolenia, dopóki morze i wszystkie jego dzieci nie zamilkną... zwłaszcza ci obrzydliwi ryboludzie.', 0),
(1429, 'koKR', '$GOdważny:Odważna; jesteś, skoro tu $gprzyszedłeś:przyszłaś;. $GOdważny:Odważna; albo $ggłupi:głupia;...', 0),
(1430, 'koKR', 'Czeka na ciebie baryłka wina, gdy tylko ci się uda, $N. Wypada, żebym sam spróbował towaru, zanim wyślę go klientom.', 0),
(1445, 'koKR', 'Jeśli fetysze Atal\'ai mają moc przywołania Hakkara i spełnienia proroctwa Jammal\'ana, trzeba je zdobyć. Horda musi poznać taką moc!', 0),
(2623, 'koKR', 'Czekam na rozkazy.', 0),
(2681, 'koKR', 'To niełatwe zadanie, $N. Nie poddawaj się!', 0),
(2744, 'koKR', 'Co tu robisz?', 0),
(2784, 'koKR', 'Posłuchaj, co mam do powiedzenia.', 0),
(2801, 'koKR', 'Posłuchaj, co mam do powiedzenia, $N.', 0),
(3374, 'koKR', 'Oto jesteśmy, $N, na kolejnym rozdrożu. Nadszedł czas, by dokonać następnego wyboru. Co wybierasz, $gśmiertelniku:śmiertelniczko;?', 0),
(3627, 'koKR', 'Trzy utworzą jedno, jedno wskaże drogę.', 0),
(3628, 'koKR', 'Nie ma się już czego bać.', 0),
(8423, 'koKR', 'Płonące kolce piekielnych dzików zostawiają straszne blizny. Nie bój się bólu ani oszpecenia, $gwojowniku:wojowniczko;, to nic w porównaniu z więzieniem, w którym tkwię.', 0),
(8424, 'koKR', 'Cienioprzysięgłych nie tak łatwo pokonać, prawda? Ale jesteś $gwojownikiem:wojowniczką; i albo zwyciężysz, albo zginiesz, próbując.', 0),
(8425, 'koKR', 'Już $gwróciłeś:wróciłaś;? Czas płynie dla mnie inaczej, może to rzeczywiście była dla ciebie długa podróż...', 0),
(9440, 'koKR', '$GNakarmiłeś:Nakarmiłaś; ich schwytane zwierzęta wszystkimi kąskami? Zaraz! Chyba nie $gdałeś:dałaś; ani jednego temu głupiemu człowiekowi, którego trzymają tam w klatce?$B$BOch, dobrze! To byłoby marnotrawstwo!', 0),
(9448, 'koKR', 'Postępujesz słusznie, $N. Zagubieni wycierpieli już tak wiele. Nie powinni znosić jeszcze tego upokorzenia.', 0),
(9610, 'koKR', 'Nie mogę się doczekać, aż zbierzesz dość artefaktów Atal\'ai, bym mógł zacząć je badać. Chętnie się dowiem, co się stało z ich niegdyś wielką cywilizacją.', 0);
INSERT INTO `quest_greeting_locale` (`ID`, `type`, `locale`, `Greeting`, `VerifiedBuild`) VALUES
(1776, 0, 'koKR', 'Tak wiele życia spędziliśmy w ucieczce, że wspomnienia spokojnych czasów stają się coraz odleglejsze.', 0),
(5591, 0, 'koKR', 'Ta chlewnia to nie szczyt wygody, ale ma swoją historię, więc Stonard musi być dla kogoś ważny. Założę się, że dlatego tu siedzimy. Na pewno nie dla widoków – nawet nie przypomina domu.', 0),
(5598, 0, 'koKR', 'Czego ode mnie chcesz?', 0);
