INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES
(1071, 'koKR', 'Dowódco,\n\nWracaj do Orgrimmaru. Twoje siły niewystarczające. Musimy ponownie ocenić położenie w świetle nowych wieści.\n\nLiczni Cienioprzysięgli i ogry. Mrocznego Portalu strzegą demony.\n\n– Thrall, wódz Hordy\n', 0);
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES
(7668, 2, 0, 'koKR', 'Kamień wiązania pęka i uwalnia duszę, którą więził.'),
(7669, 2, 0, 'koKR', 'Kamień wiązania pęka i uwalnia duszę, którą więził.'),
