INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText`, `FemaleText`, `VerifiedBuild`) VALUES
(1854, 'koKR', 'Chodźmy stąd.', '', 0),
(1855, 'koKR', 'Dziękuję, $n. Zawsze będę cię pamiętał. Moją szkatułę znajdziesz w moim obozie, na północ od Stonardu.', '', 0),
(1856, 'koKR', '%s znika na bagnach.', '', 0),
(1949, 'koKR', 'Niniejszym niszczę te narzędzia zła! Za Hordę!', '', 0),
(2076, 'koKR', '%s szeptem zdradza sekret otwarcia swojej szkatuły – $n już go zna.', '', 0),
(3641, 'koKR', 'WOOOOOOOLNOOOOŚĆ!', '', 0),
(3642, 'koKR', '%s słabnie w cielesnej powłoce. Zauważasz, że Kamień wiązania obok stwora jarzy się! Uderz teraz!', '', 0),
(3681, 'koKR', 'Nareszcie męka ustaje...', '', 0),
(3682, 'koKR', 'Pozdrów ode mnie dowódcę Trebora.', '', 0),
(3683, 'koKR', 'Plugawiciel... trzeba ostrzec Thralla...', '', 0),
(3684, 'koKR', 'To nie była jego wina. Powiedz mu to...', '', 0),
(3685, 'koKR', 'Nareszcie wolny od jego przeklętego uścisku. Ojcze, idę do ciebie...', '', 0),
(4470, 'koKR', 'Wiem, kim jesteś, $n. Los i siły, które go przekraczają, przywiodły cię do mnie w jakimś celu, a ja nie czerpię przyjemności z udziału w nim. W nadchodzących czasach podejmiesz wiele decyzji i mam nadzieję, że starczy ci mądrości, by podjąć te właściwe.$B$BUwierz mi, kiedy ci to mówię – właściwe wybory istnieją.', '', 0),
(4471, 'koKR', 'Co taki elf jak ty robi w takiej jaskini?', 'Co taki elf jak ty robi w takiej jaskini?', 0),
(4472, 'koKR', 'Jesteś bardzo $gdociekliwy:dociekliwa;, choć ta dociekliwość zdradza ogólny brak zrozumienia. Mówię tak, bo gdybyś $gprzybył:przybyła; tu w określonym celu, twoje pytanie wydawałoby się bezcelowe.$B$BTo powiedziawszy, życzę ci miłego dnia.', '', 0),
(4474, 'koKR', 'Znasz kogoś... a raczej coś... o imieniu Eranikus?', 'Znasz kogoś... a raczej coś... o imieniu Eranikus?', 0),
(4475, 'koKR', 'Wiesz, że znam, $gśmiertelniku:śmiertelniczko; – porzucam tu sporo pozorów i radzę ci zrobić to samo.$B$B$GPrzybyłeś:Przybyłaś; tu najwyraźniej dlatego, że wiesz, iż to, co posiadasz, zdobyte dzięki twoim czynom w Zatopionej Świątyni Atal\'ai, przywiodło cię do mnie w konkretnym celu. Tym celem jest ukojenie mojego towarzysza... mojego brata. Uwięziono go w koszmarze we wnętrzu samego Snu. Sam nie zdoła się uwolnić.', '', 0),
(4476, 'koKR', 'Co mu się w ogóle stało? Kiedy go... $gspotkałem:spotkałam;, był dość wrogo nastawiony.', 'Co mu się w ogóle stało? Kiedy go... $gspotkałem:spotkałam;, był dość wrogo nastawiony.', 0),
(4477, 'koKR', 'Winien jest bóg, którego przywołały trolle Atal\'ai. Zniszczyliśmy fizyczne wcielenie boga i zatopiliśmy świątynię, ale bóg okazał się o wiele silniejszy, niż nawet my przewidywaliśmy. Jego ziarno zepsucia zapuściło głębokie korzenie i wypaczało wszystko na swojej drodze.$B$BEranikusowi powierzono pieczę nad zatopioną świątynią, by ani prości Atal\'ai, ani ich bóg nigdy więcej nie powstali. Stał się nieświadomą ofiarą tego zepsucia, a my – ofiarami własnego niedocenienia jego siły.', '', 0),
(4478, 'koKR', 'Mam część esencji Eranikusa. Czego od niej chcesz... albo ode mnie?', 'Mam część esencji Eranikusa. Czego od niej chcesz... albo ode mnie?', 0),
(4479, 'koKR', 'To, że tu jesteś, jest pierwszym krokiem... słusznym wyborem, jeśli wolisz, w niesieniu pomocy Stadu Ysery.$B$BByć może jesteś tu wyłącznie dla osobistych korzyści, a może z moralnego obowiązku. Żaden z tych powodów sam w sobie nie jest ważny, lecz oba są w istocie kluczowe dla tego celu: to męka, którą znosi Eranikus, wyrwała mnie ze Snu, a teraz moim zadaniem jest położyć kres jego cierpieniu. Proszę cię, byś $gpomógł:pomogła; mi w tym dziele.\n', '', 0),
(4480, 'koKR', 'Zastanowię się nad tym, co mi powiedziałeś.', 'Zastanowię się nad tym, co mi powiedziałeś.', 0),
(4481, 'koKR', 'Dałem ci kamień przysięgi Stada Ysery, $n. Gdy będziesz $ggotów:gotowa; i w stanie nam pomóc, użyj go, a wtedy będziemy mogli zacząć.', '', 0),
(7124, 'koKR', 'Pomocy! Proszę, musisz mi pomóc!', '', 0),
(7774, 'koKR', 'Sam wódz Thrall poprosił mnie, bym tu przybył. Posłuchać go to był zaszczyt, a i trudu w tym nie ma. Lepszego przydziału niż Stonard nie mógłbym sobie wymarzyć. W tym błocie rośnie niemal każde zioło, jakiego mogę potrzebować.', '', 0),
(9589, 'koKR', 'Nie mogę pozwolić ci wejść do Świątyni! Muszę cię zniszczyć dla twojego własnego dobra!', '', 0),
(13495, 'koKR', '', 'Ale będzie zabawa! Nie sądzisz, $gmój drogi:moja droga;?', 0),
(13504, 'koKR', 'Pozdrawiam. Jestem anachoreta Avuun z ludu draenei. Badam tu Zagubionych z Ugorowego Sanktuarium w nadziei, że znajdę lekarstwo na ich stan.', '', 0),
(14065, 'koKR', 'Magtoorze, dziękuję, że pozwoliłeś mi tu z wami zostać. Jestem pewien, że wiele możemy się od siebie nauczyć. Chętnie dowiem się wszystkiego, czego się da, o Zagubionych na wschodzie.', '', 0),
(14068, 'koKR', 'Oczywiście, przyjacielu. Możesz zostać z nami, jak długo zechcesz.', '', 0),
(14075, 'koKR', 'Dlaczego handlujecie z Hordą? Jej plugawe obyczaje są poniżej waszej godności.', '', 0),
(14081, 'koKR', 'Nie mamy wyboru. Jeśli nie będziemy okazywać szacunku Hordzie, na pewno zmiażdżą nas z pobliskiego Stonardu! Obawiam się, że nawet ty i twoi przyjaciele nie zdołalibyście ich powstrzymać.', '', 0),
(14085, 'koKR', 'Muszę znaleźć sposób, by położyć kres złu, które Cersei Śpiewaczka Zmierzchu wyrządza naszym zagubionym braciom i siostrom!', '', 0),
(14087, 'koKR', 'Uważaj, Avuunie. Jeden z kupców, z którymi handluję w Stonardzie, słyszał, jak bredzi o jakiejś strasznej chorobie, którą próbuje udoskonalić. Mówią, że ma jej użyć przeciwko draenei!', '', 0),
(14088, 'koKR', 'Anachoreto, to dla nas zaszczyt, że tu jesteś, ale jestem ciekaw, co naprawdę spodziewasz się osiągnąć?', '', 0),
(14089, 'koKR', 'Magtoorze, wierzę, że istnieje sposób, by zawrócić Zagubionych znad krawędzi. Badając ich, znajdę sposób, by uleczyć ich z energii spaczenia, która ich pochłonęła. A dzięki temu zdołam też odwrócić szkody, jakich doznali Złamani.', '', 0),
(14094, 'koKR', '', 'Hahaha! Ten głupiec nigdy się nie dowie, co knuję! A jeśli nawet, to dla draenei będzie już za późno!', 0),
(14095, 'koKR', '', 'Te orki to głupcy! Tyle mocy w pobliżu, tylko czeka, by ją wziąć, a oni siedzą z założonymi rękami i patrzą, jak inni grabią bogactwa!', 0),
(14096, 'koKR', '', 'Nie mogę się doczekać, aż zobaczę efekty tej najnowszej partii!', 0),
(14097, 'koKR', '', 'Avuun śmie mi się sprzeciwiać?! Zmiażdżę go! Kiedy skończę z draenei, będą żałować, że nie są Zagubionymi!', 0),
(14098, 'koKR', '', 'Och, czy mógłbyś choć na chwilę przestać oglądać paznokcie i klepać się po tyłku? Naprawdę, nikogo to nie obchodzi!', 0),
(14099, 'koKR', '', 'Głodny jesteś? Bo ja jestem głodna. Nie zniosę już myśli o peklowanym steku z szynki od Thultasha. Gdybyśmy tylko mogli dostać tej soczystej pieczonej przepiórki!', 0),
(14101, 'koKR', '', 'Muszę zaczerpnąć świeżego powietrza, choć na tych bagnach próżno go szukać! Wychodzę na chwilę. Posprzątaj trochę, kiedy mnie nie będzie, dobrze?', 0),
(14102, 'koKR', '', 'Musisz za mną wszędzie chodzić? <wzdycha>', 0),
(14105, 'koKR', 'Jej metody są tchórzliwe. Przypomina mi aptekarzy Porzuconych.', '', 0),
(14106, 'koKR', '', 'Masz mi coś do powiedzenia prosto w twarz?', 0),
(14107, 'koKR', '', 'Tak myślałam!', 0),
(14982, 'koKR', 'Witaj, $N. Jestem jednym z tych, których nazywa się Złamanymi. Podobnie jak Zagubionych, choć nie tak dotkliwie jak ich, dotknęły nas energie spaczenia, które odmieniły nasze pierwotne draenejskie postacie.', '', 0),
(26990, 'koKR', 'Większość moich pobratymców gardzi „barbarzyńskimi” obyczajami Hordy, a niegdyś i ja się do nich zaliczałem. Gdy po raz pierwszy wysłano mnie w to nieco wilgotne i... wonne miejsce, przeklinałem swój los.$b$bW trakcie moich badań nauczyłem się jednak doceniać otoczenie. Ma w sobie pewien urok, nie sądzisz?$b$bAch, moje badania miały oczywiście pozwolić innym magom powracać tu za pomocą zaklęcia. Mam cię go nauczyć?', '', 0),
(26992, 'koKR', 'Ach, uwielbiam zapach Stonardu! Pachnie jak... jak... orkowy pot. I zgnilizna. A jednak razem dają całkiem przyjemny efekt! To zapach, do którego trzeba się przyzwyczaić.', '', 0),
(26993, 'koKR', 'Goście narzekają na wyjątkowo wilgotne powietrze, a mnie ono służy na cerę! Sucha skóra nie dodaje uroku.', '', 0),
(26994, 'koKR', 'To wstyd, straszny wstyd, że moi pobratymcy nie widzą, jakie korzyści płyną z prawdziwego zanurzenia się w obcej kulturze.', '', 0),
(26995, 'koKR', 'Oto jestem, w toporni ciosanej kamiennej wieży przycupniętej na bagnistym, błotnistym gruncie, a chmary meszek fruwają swobodnie przez otwarte drzwi; stoję wśród zgarbionych zielonoskórych postaci o wątpliwej higienie i prostackich manierach. Nigdy nie byłem szczęśliwszy.', '', 0),
(26996, 'koKR', 'Zanim mnie tu przydzielono, tylko słyszałem o odmładzającym wpływie kąpieli błotnej na skórę. Gdy po raz pierwszy potknąłem się o korzeń, doświadczyłem wszystkich jej dobrodziejstw! Niesamowite, co potrafi natura, nawet bez odrobiny magii.', '', 0),
(26997, 'koKR', 'Do dziś się zastanawiam, dlaczego to właśnie mnie wybrano na tę placówkę. Mogę się tylko domyślać, że przełożony uznał, iż wyjątkowo się do tego nadaję i szybko przywyknę do osobliwej kultury Hordy, choć słyszałem naprawdę złośliwą plotkę, że to dlatego, że za dużo mówię.', '', 0),
(27000, 'koKR', 'Cicho bądź.', '', 0),
(27001, 'koKR', 'Pamiętasz, jak było cicho, zanim przyszły tu elfy? Tęsknię za tym.', '', 0),
(27002, 'koKR', 'Zamknij się.', '', 0),
(27003, 'koKR', 'Sam nie wiem, które z nich jest bardziej szalone.', '', 0),
(27004, 'koKR', 'Oddałbym swój tłuczek za zatyczki do uszu.', '', 0),
(27007, 'koKR', 'Musisz nauczyć się doceniać otoczenie, Cersei!', '', 0);
